 var _ Metric = (*Meter)(nil)

 // Metric interface attempts to abstract high-level aspects of the observability features,
 // this would make it much easier to swap the base sdk without having to change too
 // many implementation details.
 type Metric interface {
 	// Register gives a name to the metric and initializes the provider.
 	Register(name string)

 	// Dump is responsible to read the metrics and output all the gathered data.
 	Dump(ctx context.Context) (any, error)

 	// Close shutsdown the meter.
 	Close(ctx context.Context) error
 }

 // Meter is currently wrapping opentelemetry meter functionalities while adhering to
 // the Metric interface functionality.
 type Meter struct {
 	name        string
 	meter       metric.Meter
 	mu          sync.Mutex
 	instruments []*metricInstrument
 }

 type instrumentKind int

 const (
 	counterInstrument instrumentKind = iota
 	histogramInstrument
 )

 var defaultHistogramBounds = []float64{
 	0, 5, 10, 25, 50, 75, 100, 250, 500, 750, 1000, 2500, 5000, 7500, 10000,
 }

 type metricInstrument struct {
 	kind instrumentKind
 	name string
 	unit unit.Unit

 	counterValue int64
 	histValues   []int64
 }

 type int64Counter struct {
 	noop.Int64Counter
 	meter      *Meter
 	instrument *metricInstrument
 }

 type int64Histogram struct {
 	noop.Int64Histogram
 	meter      *Meter
 	instrument *metricInstrument
 }

 // NewMeter returns a new meter.
 func NewMeter() Meter {
 	return Meter{}
 }

 // Register gives a name to the metric and initializes the provider.
 func (m *Meter) Register(name string) {
 	m.mu.Lock()
 	defer m.mu.Unlock()

 	m.name = name
 	m.meter = noop.NewMeterProvider().Meter(name)
 	m.instruments = nil
 }

 // Dump is responsible to read the metrics and output all the gathered data.
 func (m *Meter) Dump(ctx context.Context) (any, error) {
 	return m.collect(), nil
 }

 // Close shutsdown the meter.
 func (m *Meter) Close(ctx context.Context) error {
 	return nil
 }

 // GetSyncHistogram returns a new histogram with the given name and unit.
 func (m *Meter) GetSyncHistogram(
 	name string,
 	unit unit.Unit,
 ) (metric.Int64Histogram, error) {
 	m.mu.Lock()
 	defer m.mu.Unlock()

 	instrument := &metricInstrument{
 		kind: histogramInstrument,
 		name: name,
 		unit: unit,
 	}
 	m.instruments = append(m.instruments, instrument)
 	return int64Histogram{
 		instrument: instrument,
 		meter:      m,
 	}, nil
 }

 // GetSyncCounter returns a new counter with the given name and unit.
 func (m *Meter) GetSyncCounter(
 	name string,
 	unit unit.Unit,
 ) (metric.Int64Counter, error) {
 	m.mu.Lock()
 	defer m.mu.Unlock()

 	instrument := &metricInstrument{
 		kind: counterInstrument,
 		name: name,
 		unit: unit,
 	}
 	m.instruments = append(m.instruments, instrument)
 	return int64Counter{
 		instrument: instrument,
 		meter:      m,
 	}, nil
 }

 // DumpScopeMetricsString returns a string representation of the metrics.
 func (m *Meter) DumpScopeMetricsString(ctx context.Context) (string, error) {
 	data := m.collect()
 	jsonBytes, err := json.MarshalIndent(data.ScopeMetrics, "", "  ")

 	if err != nil {
 		return "", err
 	}

 	return string(jsonBytes), nil
 }

 // Get returns the meter.
 func (m *Meter) Get() metric.Meter {
 	return m.meter
 }

 func (m *Meter) collect() metricdata.ResourceMetrics {
 	m.mu.Lock()
 	defer m.mu.Unlock()

 	scopeMetrics := metricdata.ScopeMetrics{
 		Scope: instrumentation.Scope{
 			Name: m.name,
 		},
 	}
 	for _, instrument := range m.instruments {
 		scopeMetrics.Metrics = append(scopeMetrics.Metrics, instrument.toMetricData())
 	}
 	if len(scopeMetrics.Metrics) == 0 {
 		return metricdata.ResourceMetrics{}
 	}
 	return metricdata.ResourceMetrics{
 		ScopeMetrics: []metricdata.ScopeMetrics{scopeMetrics},
 	}
 }

 func (i *metricInstrument) toMetricData() metricdata.Metrics {
 	data := metricdata.Metrics{
 		Name: i.name,
 		Unit: string(i.unit),
 	}

 	switch i.kind {
 	case counterInstrument:
 		data.Data = metricdata.Sum[int64]{
 			DataPoints: []metricdata.DataPoint[int64]{
 				{Value: i.counterValue},
 			},
 			Temporality: metricdata.CumulativeTemporality,
 			IsMonotonic: true,
 		}
 	case histogramInstrument:
 		data.Data = metricdata.Histogram{
 			DataPoints: []metricdata.HistogramDataPoint{
 				{
 					Count:        uint64(len(i.histValues)),
 					Bounds:       append([]float64(nil), defaultHistogramBounds...),
 					BucketCounts: i.histogramBucketCounts(),
 					Sum:          i.histogramSum(),
 				},
 			},
 			Temporality: metricdata.CumulativeTemporality,
 		}
 	}

 	return data
 }

 func (i *metricInstrument) histogramBucketCounts() []uint64 {
 	buckets := make([]uint64, len(defaultHistogramBounds)+1)
 	for _, value := range i.histValues {
 		bucketIndex := len(defaultHistogramBounds)
 		for index, bound := range defaultHistogramBounds {
 			if float64(value) <= bound {
 				bucketIndex = index
 				break
 			}
 		}
 		buckets[bucketIndex]++
 	}
 	return buckets
 }

 func (i *metricInstrument) histogramSum() float64 {
 	var sum float64
 	for _, value := range i.histValues {
 		sum += float64(value)
 	}
 	return sum
 }

 func (c int64Counter) Add(ctx context.Context, incr int64, options ...metric.AddOption) {
 	c.meter.mu.Lock()
 	defer c.meter.mu.Unlock()

 	c.instrument.counterValue += incr
 }

